import{getSettings,saveSettings}from'../shared/storage.js';import{normalizeDomain}from'../shared/whitelist.js';const $=s=>document.querySelector(s);let settings;function render(){$('#anger').value=settings.angerLevel;$('#audio-enabled').checked=settings.audioEnabled;$('#volume').value=settings.volume;$('#intervention').value=settings.intervention;$('#grace').value=settings.graceSeconds;$('#domains').innerHTML='';settings.whitelist.forEach(domain=>{const li=document.createElement('li');li.textContent=domain;const b=document.createElement('button');b.className='remove';b.textContent='Remove';b.onclick=async()=>{settings.whitelist=settings.whitelist.filter(x=>x!==domain);await persist()};li.append(b);$('#domains').append(li)})}async function persist(){await saveSettings(settings);render();$('#saved').textContent='Saved locally.';setTimeout(()=>$('#saved').textContent='',1200)}['anger','audio-enabled','volume','intervention','grace'].forEach(id=>$('#'+id).addEventListener('change',async()=>{settings={...settings,angerLevel:$('#anger').value,audioEnabled:$('#audio-enabled').checked,volume:Number($('#volume').value),intervention:$('#intervention').value,graceSeconds:Math.max(0,Math.min(60,Number($('#grace').value)||0))};await persist()}));$('#add').onclick=async()=>{const domain=normalizeDomain($('#domain').value);if(domain&&!settings.whitelist.includes(domain))settings.whitelist=[...settings.whitelist,domain];$('#domain').value='';await persist()};getSettings().then(s=>{settings=s;render()});
